$: s("[hh ~ ~ ~] [hh ~ ~ ~] [hh ~ ~ ~] [hh ~ hh ~]").bank("RolandTR909").gain(0.43).lpf(6320).mask(section9).velocity(section9).orbit(1).analyze("hats")
$: s("~ [~ ~ oh ~] ~ [~ ~ oh ~]").bank("RolandTR909").gain(0.38).lpf(6320).mask(section9).velocity(section9).orbit(1).analyze("hats")
$: s("sd*16").bank("RolandTR909").gain(saw.range(.15, .75)).mask("<0!17 1 0!2>").mask(section9).velocity(section9).orbit(1).analyze("snare")
$: s("cr").bank("RolandTR909").gain(.55).room(.4).mask("<0!18 1 0>").mask(section9).velocity(section9).orbit(1).analyze("fx")

// ========== bass ==========
// Crescendo · bars 1-31 · pattern B
// Bass · Pumping (sidechain)
$: note("<a1>").transpose(-5).struct("[x x x x] [x x x x] [x x x x] [x x x x]")
  .s("sine").lpf(600).lpq(2)
  .decay(.2).sustain(.6).postgain("[.1 .4 .75 1] [.1 .4 .75 1] [.1 .4 .75 1] [.1 .4 .75 1]").gain(0.7).mask(section1).velocity(section1).orbit(2).analyze("bass")
// Crescendo 2 · bars 32-84 · pattern B
$: note("<a1 g1 g1 f1 f1 g1 g1 a1>").transpose(-5).struct("[x x x x] [x x x x] [x x x x] [x x x x]")
  .s("sine").lpf(600).lpq(2)
  .decay(.2).sustain(.6).postgain("[.1 .4 .75 1] [.1 .4 .75 1] [.1 .4 .75 1] [.1 .4 .75 1]").gain(0.7).mask(section2).velocity(section2).orbit(2).analyze("bass")
// Intro · bars 85-92 · pattern A
// Bass · Long sub
$: note("<a1 a1 g1 g1>").transpose(-5).struct("x")
  .s("sine").lpf(400).lpq(2)
  .decay(.6).sustain(.8).gain(0.35).mask(section3).velocity(section3).orbit(2).analyze("bass")
// Strofa A · bars 93-101 · pattern B
// Bass · Pumping (sidechain)
$: note("<f1 f1 g1 g1 a1 a1 g1 g1>").transpose(-5).struct("[x x x x] [x x x x] [x x x x] [x x x x]")
  .s("sine").lpf(600).lpq(2)
  .decay(.2).sustain(.6).postgain("[.1 .4 .75 1] [.1 .4 .75 1] [.1 .4 .75 1] [.1 .4 .75 1]").gain(0.7).mask(section4).velocity(section4).orbit(2).analyze("bass")
// Strofa B · bars 103-110 · pattern B
$: note("<g1 g1 f1 f1 g1 g1 a1 a1>").transpose(-5).struct("[x x x x] [x x x x] [x x x x] [x x x x]")
  .s("sine").lpf(600).lpq(2)
  .decay(.2).sustain(.6).postgain("[.1 .4 .75 1] [.1 .4 .75 1] [.1 .4 .75 1] [.1 .4 .75 1]").gain(0.7).mask(section6).velocity(section6).orbit(2).analyze("bass")
// Breakdown · bars 111-116 · pattern A
// Bass · Long sub
$: note("<g1 g1 a1 a1>").transpose(-5).struct("x")
  .s("sine").lpf(400).lpq(2)
  .decay(.6).sustain(.8).gain(0.4).mask(section7).velocity(section7).orbit(2).analyze("bass")
// Finale · bars 119-138 · pattern B
// Bass · Pumping (sidechain)
$: note("<g1 g1 f1 f1 g1 g1 a1 a1>").transpose(-5).struct("[x x x x] [x x x x] [x x x x] [x x x x]")
  .s("sine").lpf(600).lpq(2)
  .decay(.2).sustain(.6).postgain("[.1 .4 .75 1] [.1 .4 .75 1] [.1 .4 .75 1] [.1 .4 .75 1]").gain(0.8).mask(section9).velocity(section9).orbit(2).analyze("bass")

// ========== arp ==========
// Crescendo · bars 1-31 · pattern A
// Arpeggio · Up and down, 16ths
$: note("<[a3 c4 e4 a4 e4 c4 a3 c4 a3 c4 e4 a4 e4 c4 a3 c4]>").transpose(-5)
  .s("triangle").lpf(2600).lpq(2)
  .decay(.15).sustain(.15).gain(0.28).degradeBy(0.35).mask(section1).velocity(section1).orbit(3).analyze("arp")
// Crescendo 2 · bars 32-84 · pattern A
$: note("<[a3 c4 e4 a4 e4 c4 a3 c4 a3 c4 e4 a4 e4 c4 a3 c4] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3] [f3 a3 c4 f4 c4 a3 f3 a3 f3 a3 c4 f4 c4 a3 f3 a3] [f3 a3 c4 f4 c4 a3 f3 a3 f3 a3 c4 f4 c4 a3 f3 a3] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3] [a3 c4 e4 a4 e4 c4 a3 c4 a3 c4 e4 a4 e4 c4 a3 c4]>").transpose(-5)
  .s("triangle").lpf(2600).lpq(2)
  .decay(.15).sustain(.15).gain(0.28).degradeBy(0.35).mask(section2).velocity(section2).orbit(3).analyze("arp")
// Intro · bars 85-92 · pattern A
$: note("<[a3 c4 e4 a4 e4 c4 a3 c4 a3 c4 e4 a4 e4 c4 a3 c4] [a3 c4 e4 a4 e4 c4 a3 c4 a3 c4 e4 a4 e4 c4 a3 c4] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3]>").transpose(-5)
  .s("triangle").lpf("<2000 2200 2400 2600 1200 1400 1600 1800>").lpq(2)
  .decay(.15).sustain(.15).gain("<0.22 0.24 0.26 0.28 0.15 0.17 0.19 0.21>").degradeBy(0.35).mask(section3).velocity(section3).orbit(3).analyze("arp")
// Strofa A · bars 93-101 · pattern A
$: note("<[f3 a3 c4 f4 c4 a3 f3 a3 f3 a3 c4 f4 c4 a3 f3 a3] [f3 a3 c4 f4 c4 a3 f3 a3 f3 a3 c4 f4 c4 a3 f3 a3] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3] [a3 c4 e4 a4 e4 c4 a3 c4 a3 c4 e4 a4 e4 c4 a3 c4] [a3 c4 e4 a4 e4 c4 a3 c4 a3 c4 e4 a4 e4 c4 a3 c4] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3]>").transpose(-5)
  .s("triangle").lpf(2600).lpq(2)
