  .s("triangle").lpf(900).lpq(2)
  .decay(.15).sustain(.15).gain(0.2).degradeBy(0.35).mask(section7).velocity(section7).orbit(3).analyze("arp")
// Riser · bars 117-118 · pattern A
$: note("<[a3 c4 e4 a4 e4 c4 a3 c4 a3 c4 e4 a4 e4 c4 a3 c4] [a3 c4 e4 a4 e4 c4 a3 c4 a3 c4 e4 a4 e4 c4 a3 c4] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3]>").transpose(-5)
  .s("triangle").lpf("<1400 2600>").lpq(2)
  .decay(.15).sustain(.15).gain(0.22).degradeBy(0.35).mask("<1 [1 0]>").mask(section8).velocity(section8).orbit(3).analyze("arp")
// Finale · bars 119-138 · pattern A
$: note("<[g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3] [f3 a3 c4 f4 c4 a3 f3 a3 f3 a3 c4 f4 c4 a3 f3 a3] [f3 a3 c4 f4 c4 a3 f3 a3 f3 a3 c4 f4 c4 a3 f3 a3] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3] [g3 b3 d4 g4 d4 b3 g3 b3 g3 b3 d4 g4 d4 b3 g3 b3] [a3 c4 e4 a4 e4 c4 a3 c4 a3 c4 e4 a4 e4 c4 a3 c4] [a3 c4 e4 a4 e4 c4 a3 c4 a3 c4 e4 a4 e4 c4 a3 c4]>").transpose(-5)
  .s("triangle").lpf(3000).lpq(2)
  .decay(.15).sustain(.15).gain(0.3).degradeBy(0.35).mask(section9).velocity(section9).orbit(3).analyze("arp")

// ========== hook ==========
// Crescendo · bars 1-31 · pattern A
// Hook · Decade
$: n("<[0 0 0 1 2 0 2 0] [0 0 4 1 0 0 2 0] [2 -1 -1 ~ -1 1 2 1] [-1 ~ -1 ~ -1 -1 2 2] [4 ~ 4 3 2 ~ 1 0] [2 ~ 2 1 0 ~ -1 0] [1 1 1 ~ 1 2 1 -1] [-1 ~ ~ ~ 1 ~ 2 ~]>").scale("E4:minor")
  .s("square").lpf(800)
  .decay(.2).sustain(.3).delay(0).room(.3).gain(0.24).degradeBy(0.6).mask(section1).velocity(section1).orbit(4).analyze("hook")
// Crescendo 2 · bars 32-84 · pattern A
$: n("<[0 0 4 1 0 0 2 0] [2 -1 -1 ~ -1 1 2 1] [-1 ~ -1 ~ -1 -1 2 2] [4 ~ 4 3 2 ~ 1 0] [2 ~ 2 1 0 ~ -1 0] [1 1 1 ~ 1 2 1 -1] [-1 ~ ~ ~ 1 ~ 2 ~] [0 0 0 1 2 0 2 0]>").scale("E4:minor")
  .s("square").lpf(800)
  .decay(.2).sustain(.3).delay(0).room(.3).gain(0.24).degradeBy(0.6).mask(section2).velocity(section2).orbit(4).analyze("hook")
// Strofa B · bars 103-110 · pattern A
$: n("<[2 -1 -1 ~ -1 1 2 1] [-1 ~ -1 ~ -1 -1 2 2] [4 ~ 4 3 2 ~ 1 0] [2 ~ 2 1 0 ~ -1 0] [1 1 1 ~ 1 2 1 -1] [-1 ~ ~ ~ 1 ~ 2 ~] [0 0 0 1 2 0 2 0] [0 0 4 1 0 0 2 0]>").scale("E4:minor")
  .s("square").lpf(800)
  .decay(.2).sustain(.3).delay(0).room(.3).gain(0.24).degradeBy(0.6).mask(section6).velocity(section6).orbit(4).analyze("hook")
// Finale · bars 119-138 · pattern A
$: n("<[2 -1 -1 ~ -1 1 2 1] [-1 ~ -1 ~ -1 -1 2 2] [4 ~ 4 3 2 ~ 1 0] [2 ~ 2 1 0 ~ -1 0] [1 1 1 ~ 1 2 1 -1] [-1 ~ ~ ~ 1 ~ 2 ~] [0 0 0 1 2 0 2 0] [0 0 4 1 0 0 2 0]>").scale("E4:minor")
  .s("square").lpf(800)
  .decay(.2).sustain(.3).delay(0).room(.3).gain(0.28).degradeBy(0.6).mask(section9).velocity(section9).orbit(4).analyze("hook")

